from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
MAIN=ROOT/"app"/"src"/"main"/"java"/"fr"/"manubotelho"/"mestaches"/"MainActivity.java"
MANIFEST=ROOT/"app"/"src"/"main"/"AndroidManifest.xml"

text=MAIN.read_text(encoding="utf-8")

# Continuous in-app speech recognition. Unlike ACTION_RECOGNIZE_SPEECH, this keeps
# the editor open, appends each recognized chunk, and automatically starts a new
# listening session after natural pauses until the user taps Stop.
if 'import android.Manifest;' not in text:
    text=text.replace('import android.app.Activity;\n', 'import android.Manifest;\nimport android.app.Activity;\n', 1)
if 'import android.content.pm.PackageManager;' not in text:
    text=text.replace('import android.content.SharedPreferences;\n', 'import android.content.SharedPreferences;\nimport android.content.pm.PackageManager;\n', 1)
if 'import android.speech.RecognitionListener;' not in text:
    text=text.replace('import android.os.Looper;\n', 'import android.os.Looper;\nimport android.speech.RecognitionListener;\nimport android.speech.RecognizerIntent;\nimport android.speech.SpeechRecognizer;\n', 1)
if 'import java.util.ArrayList;' not in text:
    text=text.replace('import java.util.Calendar;\n', 'import java.util.ArrayList;\nimport java.util.Calendar;\n', 1)

text=text.replace(
    'static final int ADD=1001, TODO=1002, DONE=1003, TITLE=1004, DATE=1005, TIME=1006, COLORS=1007;',
    'static final int ADD=1001, TODO=1002, DONE=1003, TITLE=1004, DATE=1005, TIME=1006, COLORS=1007, VOICE_PERMISSION=8002;',
    1)

field_anchor='''    private EditText titleField;\n    private RadioButton appointmentField;'''
field_replacement='''    private EditText titleField;\n    private Button voiceButton;\n    private SpeechRecognizer voiceRecognizer;\n    private boolean voiceDictating=false;\n    private String voiceCommittedText="";\n    private final Runnable restartVoice=()->{ if (voiceDictating) listenForVoiceChunk(); };\n    private RadioButton appointmentField;'''
if field_anchor not in text:
    raise SystemExit("Champs MainActivity introuvables pour la dictée")
text=text.replace(field_anchor,field_replacement,1)

old='''        titleField.setText(saved!=null?saved.getString("draftTitle",""):task==null?"":task.title);\n        form.addView(titleField,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));\n\n        form.addView(fieldLabel("Date"));'''
new='''        titleField.setText(saved!=null?saved.getString("draftTitle",""):task==null?"":task.title);\n\n        LinearLayout titleRow=new LinearLayout(this);\n        titleRow.setOrientation(LinearLayout.HORIZONTAL);\n        titleRow.setGravity(Gravity.TOP);\n        LinearLayout.LayoutParams titleParams=new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1);\n        titleRow.addView(titleField,titleParams);\n        voiceButton=button("🎤",false);\n        voiceButton.setTextSize(24);\n        voiceButton.setContentDescription("Démarrer la dictée continue");\n        voiceButton.setMinWidth(dp(58)); voiceButton.setMinimumWidth(dp(58));\n        LinearLayout.LayoutParams micParams=new LinearLayout.LayoutParams(dp(62),ViewGroup.LayoutParams.WRAP_CONTENT);\n        micParams.setMarginStart(dp(8));\n        titleRow.addView(voiceButton,micParams);\n        voiceButton.setOnClickListener(v->{\n            if (voiceDictating) stopVoiceInput(true);\n            else startVoiceInput();\n        });\n        form.addView(titleRow,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));\n\n        form.addView(fieldLabel("Date"));'''
if old not in text:
    raise SystemExit("Zone texte de tâche introuvable pour le bouton micro")
text=text.replace(old,new,1)

anchor='''    @Override protected void onSaveInstanceState(Bundle out) {'''
insert='''    private void startVoiceInput() {\n        hideKeyboard();\n        if (Build.VERSION.SDK_INT>=23 && checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED) {\n            requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},VOICE_PERMISSION);\n            return;\n        }\n        beginContinuousVoice();\n    }\n\n    private void beginContinuousVoice() {\n        if (titleField==null) return;\n        if (!SpeechRecognizer.isRecognitionAvailable(this)) {\n            Toast.makeText(this,"La dictée vocale n’est pas disponible sur ce téléphone.",Toast.LENGTH_LONG).show();\n            return;\n        }\n        voiceCommittedText=titleField.getText().toString().trim();\n        voiceDictating=true;\n        if (voiceButton!=null) {\n            voiceButton.setText("⏹");\n            voiceButton.setContentDescription("Arrêter la dictée");\n        }\n        if (voiceRecognizer==null) {\n            voiceRecognizer=SpeechRecognizer.createSpeechRecognizer(this);\n            voiceRecognizer.setRecognitionListener(new RecognitionListener() {\n                @Override public void onReadyForSpeech(Bundle params) {}\n                @Override public void onBeginningOfSpeech() {}\n                @Override public void onRmsChanged(float rmsdB) {}\n                @Override public void onBufferReceived(byte[] buffer) {}\n                @Override public void onEndOfSpeech() {}\n                @Override public void onEvent(int eventType,Bundle params) {}\n\n                @Override public void onPartialResults(Bundle partialResults) {\n                    if (!voiceDictating || titleField==null || partialResults==null) return;\n                    ArrayList<String> results=partialResults.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);\n                    if (results==null || results.isEmpty()) return;\n                    String partial=results.get(0)==null?"":results.get(0).trim();\n                    if (partial.isEmpty()) return;\n                    setVoiceText(joinVoice(voiceCommittedText,partial));\n                }\n\n                @Override public void onResults(Bundle resultsBundle) {\n                    if (titleField==null) return;\n                    ArrayList<String> results=resultsBundle==null?null:resultsBundle.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);\n                    if (results!=null && !results.isEmpty()) {\n                        String spoken=results.get(0)==null?"":results.get(0).trim();\n                        if (!spoken.isEmpty()) {\n                            voiceCommittedText=joinVoice(voiceCommittedText,spoken);\n                            setVoiceText(voiceCommittedText);\n                        } else {\n                            setVoiceText(voiceCommittedText);\n                        }\n                    } else {\n                        setVoiceText(voiceCommittedText);\n                    }\n                    if (voiceDictating) {\n                        handler.removeCallbacks(restartVoice);\n                        handler.postDelayed(restartVoice,250);\n                    }\n                }\n\n                @Override public void onError(int error) {\n                    if (!voiceDictating) return;\n                    if (error==SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS) {\n                        stopVoiceInput(false);\n                        Toast.makeText(MainActivity.this,"Autorise le micro pour utiliser la dictée.",Toast.LENGTH_LONG).show();\n                        return;\n                    }\n                    // Silence, fin de phrase, recognizer busy or a temporary network/server\n                    // error must not end a long dictation. Start another chunk automatically.\n                    long delay=error==SpeechRecognizer.ERROR_RECOGNIZER_BUSY?650:300;\n                    handler.removeCallbacks(restartVoice);\n                    handler.postDelayed(restartVoice,delay);\n                }\n            });\n        }\n        listenForVoiceChunk();\n        Toast.makeText(this,"Dictée continue activée · appuie sur ⏹ pour arrêter",Toast.LENGTH_LONG).show();\n    }\n\n    private void listenForVoiceChunk() {\n        if (!voiceDictating || voiceRecognizer==null) return;\n        Intent voice=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);\n        voice.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);\n        voice.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.FRANCE.toLanguageTag());\n        voice.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);\n        voice.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,1);\n        voice.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_MINIMUM_LENGTH_MILLIS,30000L);\n        voice.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS,8000L);\n        voice.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS,5000L);\n        try {\n            voiceRecognizer.startListening(voice);\n        } catch (RuntimeException ex) {\n            if (voiceDictating) {\n                handler.removeCallbacks(restartVoice);\n                handler.postDelayed(restartVoice,700);\n            }\n        }\n    }\n\n    private String joinVoice(String before,String spoken) {\n        String left=before==null?"":before.trim();\n        String right=spoken==null?"":spoken.trim();\n        if (left.isEmpty()) return right;\n        if (right.isEmpty()) return left;\n        return left+" "+right;\n    }\n\n    private void setVoiceText(String value) {\n        if (titleField==null) return;\n        titleField.setText(value);\n        titleField.setSelection(titleField.length());\n    }\n\n    private void stopVoiceInput(boolean userRequested) {\n        voiceDictating=false;\n        handler.removeCallbacks(restartVoice);\n        if (voiceRecognizer!=null) {\n            try { voiceRecognizer.stopListening(); } catch (RuntimeException ignored) {}\n            try { voiceRecognizer.cancel(); } catch (RuntimeException ignored) {}\n        }\n        if (voiceButton!=null) {\n            voiceButton.setText("🎤");\n            voiceButton.setContentDescription("Démarrer la dictée continue");\n        }\n        if (userRequested) Toast.makeText(this,"Dictée arrêtée",Toast.LENGTH_SHORT).show();\n    }\n\n    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults) {\n        super.onRequestPermissionsResult(requestCode,permissions,grantResults);\n        if (requestCode!=VOICE_PERMISSION) return;\n        if (grantResults.length>0 && grantResults[0]==PackageManager.PERMISSION_GRANTED) beginContinuousVoice();\n        else Toast.makeText(this,"Le micro est nécessaire pour dicter une tâche.",Toast.LENGTH_LONG).show();\n    }\n\n    @Override protected void onSaveInstanceState(Bundle out) {'''
if anchor not in text:
    raise SystemExit("Point d'insertion dictée introuvable")
text=text.replace(anchor,insert,1)

# Release the recognizer with the Activity to avoid a stale microphone session.
destroy_anchor='''    @Override protected void onDestroy() {\n        handler.removeCallbacksAndMessages(null);'''
destroy_replacement='''    @Override protected void onDestroy() {\n        stopVoiceInput(false);\n        if (voiceRecognizer!=null) { try { voiceRecognizer.destroy(); } catch (RuntimeException ignored) {} voiceRecognizer=null; }\n        handler.removeCallbacksAndMessages(null);'''
if destroy_anchor not in text:
    raise SystemExit("onDestroy introuvable pour nettoyer la dictée")
text=text.replace(destroy_anchor,destroy_replacement,1)

MAIN.write_text(text,encoding="utf-8")

